sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0 || blur <= 0.0) return src;
    float soft = clamp((float(blurred.eval(coord).a) - 0.5) * 2.0, 0.0, 1.0);
    return src * half(soft);
}
